    $$(".toggle-directory").forEach(b=>b.onclick=async()=>{try{const show=b.dataset.show!=="true";await api(`/api/categories/${b.dataset.id}`,{method:"PUT",body:JSON.stringify({showInDirectory:show})});toast(show?"Added to All Categories":"Removed from All Categories",true);categories();}catch(e){toast(e.message);}});
    $$(".delete-cat").forEach(b=>b.onclick=async()=>{if(!confirm(`Delete collection "${b.dataset.name}"? Products will be unassigned.`))return;try{await api(`/api/categories/${b.dataset.id}`,{method:"DELETE"});toast("Collection deleted",true);categories();}catch(e){toast(e.message);}});
