    $("#content").innerHTML=`<div class="page"><div class="panel"><div class="panel-head"><div><h3>ANIME HERO WORLDS</h3><p class="muted">Control exactly which anime sections appear in the storefront hero. Upload, replace, reorder or remove them without editing code.</p></div><div class="tools"><button class="secondary" id="heroCollections">MANAGE COLLECTIONS →</button><button class="primary" id="newHero">+ ADD ANIME WORLD</button></div></div><div class="hero-admin-list">${list.map((c,i)=>`<div class="hero-admin-card"><div class="hero-admin-media">${c.heroImage||c.image?`<img src="${esc(c.heroImage||c.image)}" alt="">`:'<div class="category-placeholder">A</div>'}</div><div class="hero-admin-info"><div class="hero-admin-order">${String(i+1).padStart(2,"0")} · ${esc(c.heroTag||"ANIME COLLECTION")}</div><h3>${esc(c.name)}</h3><p>${esc(c.heroDescription||"")}</p><small>Hero image: ${esc(c.heroImage||c.image||"Not set")}</small></div><div class="hero-admin-actions"><button class="action edit-hero" data-id="${esc(c._id)}">EDIT</button><button class="action danger-btn remove-hero" data-id="${esc(c._id)}" data-name="${esc(c.name)}">REMOVE FROM HERO</button></div></div>`).join("")||'<div class="empty">No anime worlds are enabled. Add one to build your hero.</div>'}</div></div><div class="panel"><div class="panel-head"><div><h3>HOW IT WORKS</h3><p class="muted">Hero worlds are powered by your Collections. Deleting a collection removes it from the hero; removing a world here keeps the collection and its products intact.</p></div></div></div></div>`;
